//! Streaming documents attached to common profile UUIDs.

use super::super::keys::{PairKey, TripleKey};
use anyhow::Result;
use arachnea_core::persistence::{
    EntityReader, EntitySchema, EntityWriter, Field, PersistentEntity,
};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use uuid::Uuid;

/// Versioned streaming preferences initialized on first service use.
#[derive(Clone, Serialize, Deserialize)]
pub struct StreamSettings {
    /// Common profile UUID, never regenerated by streaming.
    pub profile_id: Uuid,
    /// Streaming document schema version.
    pub schema_version: i64,
    /// Monotonic settings revision.
    pub revision: i64,
    /// Streaming preference document; validation belongs to the service.
    pub values: Value,
    /// Operation marker used for idempotent replay.
    pub last_operation_id: Uuid,
}

impl PersistentEntity for StreamSettings {
    type Key = String;
    fn key(&self) -> Self::Key {
        self.profile_id.to_string()
    }
    fn schema() -> EntitySchema {
        EntitySchema::new()
            .primary_key(Field::string("profile_id"))
            .field(Field::integer("schema_version"))
            .field(Field::integer("revision"))
            .field(Field::json("values"))
            .field(Field::string("last_operation_id"))
    }
    fn write_to(&self, writer: &mut EntityWriter) -> Result<()> {
        writer.string("profile_id", self.profile_id.to_string())?;
        writer.integer("schema_version", self.schema_version)?;
        writer.integer("revision", self.revision)?;
        writer.json("values", serde_json::to_value(&self.values)?)?;
        writer.string("last_operation_id", self.last_operation_id.to_string())?;
        Ok(())
    }
    fn read_from(reader: &EntityReader<'_>) -> Result<Self> {
        Ok(Self {
            profile_id: Uuid::parse_str(reader.string("profile_id")?)?,
            schema_version: reader.integer("schema_version")?,
            revision: reader.integer("revision")?,
            values: serde_json::from_value(reader.json("values")?.clone())?,
            last_operation_id: Uuid::parse_str(reader.string("last_operation_id")?)?,
        })
    }
}

/// Versioned home definition; fetched catalogue data is not persisted.
#[derive(Clone, Serialize, Deserialize)]
pub struct Home {
    /// Common profile UUID.
    pub profile_id: Uuid,
    /// Stable home identity.
    pub home_id: Uuid,
    /// Home definition schema version.
    pub schema_version: i64,
    /// Monotonic home revision.
    pub revision: i64,
    /// Order within the profile.
    pub navigation_order: i64,
    /// Versioned custom home definition.
    pub definition: Value,
}

impl PersistentEntity for Home {
    type Key = PairKey;
    fn key(&self) -> Self::Key {
        PairKey([self.profile_id.to_string(), self.home_id.to_string()])
    }
    fn schema() -> EntitySchema {
        EntitySchema::new()
            .primary_key(Field::string("profile_id"))
            .primary_key(Field::string("home_id"))
            .field(Field::integer("schema_version"))
            .field(Field::integer("revision"))
            .field(Field::integer("navigation_order"))
            .field(Field::json("definition"))
    }
    fn write_to(&self, writer: &mut EntityWriter) -> Result<()> {
        writer.string("profile_id", self.profile_id.to_string())?;
        writer.string("home_id", self.home_id.to_string())?;
        writer.integer("schema_version", self.schema_version)?;
        writer.integer("revision", self.revision)?;
        writer.integer("navigation_order", self.navigation_order)?;
        writer.json("definition", serde_json::to_value(&self.definition)?)?;
        Ok(())
    }
    fn read_from(reader: &EntityReader<'_>) -> Result<Self> {
        Ok(Self {
            profile_id: Uuid::parse_str(reader.string("profile_id")?)?,
            home_id: Uuid::parse_str(reader.string("home_id")?)?,
            schema_version: reader.integer("schema_version")?,
            revision: reader.integer("revision")?,
            navigation_order: reader.integer("navigation_order")?,
            definition: serde_json::from_value(reader.json("definition")?.clone())?,
        })
    }
}

