/// One profile-owned bookmark and playback progress document.
#[derive(Clone, Serialize, Deserialize)]
pub struct Bookmark {
    /// Common profile UUID.
    pub profile_id: Uuid,
    /// Provider source identity.
    pub source_id: String,
    /// Trimmed entry URL, without further canonicalization.
    pub entry: String,
    /// Bookmark document schema version.
    pub schema_version: i64,
    /// Monotonic bookmark revision.
    pub revision: i64,
    /// Server modification time in epoch milliseconds.
    pub modified_at: i64,
    /// Complete bookmark payload validated by the streaming API service.
    pub values: Value,
}

impl PersistentEntity for Bookmark {
    type Key = TripleKey;
    fn key(&self) -> Self::Key {
        TripleKey([
            self.profile_id.to_string(),
            self.source_id.clone(),
            self.entry.clone(),
        ])
    }
    fn schema() -> EntitySchema {
        EntitySchema::new()
            .primary_key(Field::string("profile_id"))
            .primary_key(Field::string("source_id"))
            .primary_key(Field::string("entry"))
            .field(Field::integer("schema_version"))
            .field(Field::integer("revision"))
            .field(Field::integer("modified_at"))
            .field(Field::json("values"))
    }
    fn write_to(&self, writer: &mut EntityWriter) -> Result<()> {
        writer.string("profile_id", self.profile_id.to_string())?;
        writer.string("source_id", self.source_id.clone())?;
        writer.string("entry", self.entry.clone())?;
        writer.integer("schema_version", self.schema_version)?;
        writer.integer("revision", self.revision)?;
        writer.integer("modified_at", self.modified_at)?;
        writer.json("values", serde_json::to_value(&self.values)?)?;
        Ok(())
    }
    fn read_from(reader: &EntityReader<'_>) -> Result<Self> {
        Ok(Self {
            profile_id: Uuid::parse_str(reader.string("profile_id")?)?,
            source_id: reader.string("source_id")?.to_string(),
            entry: reader.string("entry")?.to_string(),
            schema_version: reader.integer("schema_version")?,
            revision: reader.integer("revision")?,
            modified_at: reader.integer("modified_at")?,
            values: serde_json::from_value(reader.json("values")?.clone())?,
        })
    }
}
